     * @since 2.7.0
     */
    public String getName() {
        String name = this.getNodeName();
        if (this.isLeaf() && !isRootChild()) {
            int colonIndex = name.indexOf(":");
            if (colonIndex > 0) {
                // Strip the GET/POST/etc. off
